The previous attempt ran out of time because it made every call one after another. This version runs the requests in parallel and returns partial results if it nears the 20 s limit.

```ts
const unwrap = (r: any): any[] => Array.isArray(r) ? r : (r?.items ?? r?.issues ?? r?.comments ?? []);

const pages: any[][] = await Promise.all(
  [1, 2, 3, 4, 5, 6, 7, 8].map(p =>
    tools.list_issues({ repo: "acme/web", state: "all", page: p }).then(unwrap).catch(() => [] as any[])
  )
);

const seen = new Map<number, any>();
for (const b of pages) for (const i of b) seen.set(i.number, i);
const issues = [...seen.values()];

const counts = new Map<number, { number: number; state: string; comments: number; done: boolean }>();
for (const i of issues) counts.set(i.number, { number: i.number, state: i.state, comments: 0, done: false });

const work = Promise.all(
  issues.map(async (i) => {
    const c = counts.get(i.number)!;
    for (let page = 1; page < 50; page++) {
      const b = unwrap(await tools.list_comments({ repo: "acme/web", number: i.number, page }).catch(() => []));
      c.comments += b.length;
      if (b.length < 50) break;
    }
    c.done = true;
  })
);

await Promise.race([work, new Promise(r => setTimeout(r, 16000))]);

const all = [...counts.values()];
const finished = all.filter(c => c.done).length;
all.sort((a, b) => b.comments - a.comments || a.number - b.number);
return { totalIssues: issues.length, finished, top: all.slice(0, 10) };
```

