```ts
const unwrap = (r: any): any[] => Array.isArray(r) ? r : (r?.items ?? r?.issues ?? r?.comments ?? []);

const listPages = await Promise.all(
  Array.from({ length: 11 }, (_, k) => k + 1).map(p =>
    tools.list_issues({ repo: "acme/web", state: "all", page: p }).then(unwrap)
  )
);
const seen = new Map<number, any>();
for (const b of listPages) for (const i of b) seen.set(i.number, i);
const issues = [...seen.values()];

let errors = 0;
const results = await Promise.all(
  issues.map(async (i: any) => {
    let total = 0;
    for (let page = 1; page < 50; page++) {
      let b: any[];
      try {
        b = unwrap(await tools.list_comments({ repo: "acme/web", number: i.number, page }));
      } catch {
        errors++;
        return { number: i.number, state: i.state, comments: null };
      }
      total += b.length;
      if (b.length < 50) break;
    }
    return { number: i.number, state: i.state, comments: total };
  })
);

const ok = results.filter(r => r.comments !== null) as any[];
ok.sort((a, b) => b.comments - a.comments || a.number - b.number);
return { totalIssues: issues.length, errors, top: ok.slice(0, 5) };
```

